class Solution:
    def defangIPaddr(self, address: str) -> str:
        return address.replace(".", "[.]")

class Solution {
public:
    string defangIPaddr(string address) {
        string res = "";
        for (char c : address) {
            if (c == '.') res += "[.]";
            else res += c;
        }
        return res;
    }
};

class Solution {
    public String defangIPaddr(String address) {
        return address.replace(".", "[.]");
    }
}
